#include <iostream>
#include <fstream>
#include <string>
#include <mutex>
#include <thread>
#include <chrono>
#include <filesystem>
#include <atomic>
#include <functional>
#include <queue>
#include <condition_variable>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>

namespace fs = std::filesystem;

class RateLimiter {
private:
    std::mutex mtx_;
    int tokens_;
    int max_tokens_;
    std::chrono::steady_clock::time_point last_refill_;

public:
    RateLimiter(int max_per_second) : tokens_(max_per_second), max_tokens_(max_per_second),
        last_refill_(std::chrono::steady_clock::now()) {}

    bool try_acquire() {
        std::lock_guard<std::mutex> lock(mtx_);
        auto now = std::chrono::steady_clock::now();
        auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(now - last_refill_).count();
        if (elapsed >= 1000) {
            tokens_ = max_tokens_;
            last_refill_ = now;
        }
        if (tokens_ > 0) {
            tokens_--;
            return true;
        }
        return false;
    }
};

class RetryPolicy {
public:
    static constexpr int MAX_RETRIES = 3;
    static constexpr int BASE_DELAY_MS = 100;

    template<typename Func>
    static bool execute_with_retry(Func&& fn) {
        for (int attempt = 0; attempt <= MAX_RETRIES; attempt++) {
            if (fn()) return true;
            if (attempt < MAX_RETRIES) {
                std::this_thread::sleep_for(
                    std::chrono::milliseconds(BASE_DELAY_MS * (1 << attempt)));
            }
        }
        return false;
    }
};

class PDFOutputConfig {
public:
    std::string output_dir;
    std::string temp_dir;
    bool overwrite_existing;

    PDFOutputConfig(const std::string& out, const std::string& tmp, bool overwrite = false)
        : output_dir(out), temp_dir(tmp), overwrite_existing(overwrite) {}
};

class PDFGenerator {
private:
    RateLimiter limiter_;
    std::mutex generation_mtx_;
    PDFOutputConfig config_;

    // Reject any filename that could escape the target directory.
    static bool is_safe_filename(const std::string& filename) {
        if (filename.empty()) return false;
        if (filename == "." || filename == "..") return false;
        // Must be a single path component: no separators, no traversal.
        if (filename.find('/') != std::string::npos) return false;
        if (filename.find('\\') != std::string::npos) return false;
        // Disallow embedded NUL and control characters.
        for (unsigned char c : filename) {
            if (c == '\0') return false;
        }
        // fs::path with a single filename component must have no parent.
        fs::path p(filename);
        if (p.has_parent_path()) return false;
        if (p.is_absolute()) return false;
        if (p.filename() != p) return false;
        return true;
    }

    bool validate_output_path(const std::string& filename) {
        // Enforce that the filename is a plain single component first.
        if (!is_safe_filename(filename)) {
            return false;
        }

        fs::path output_path = fs::path(config_.output_dir) / filename;
        fs::path canonical_dir = fs::canonical(config_.output_dir);

        // Resolve the parent to check containment. The parent must exist
        // (it is the output_dir) and must be contained; if it cannot be
        // resolved or is outside the output directory, reject.
        fs::path parent = output_path.parent_path();
        std::error_code ec;
        fs::path resolved_parent = fs::canonical(parent, ec);
        if (ec) {
            return false;
        }
        std::string dir_str = canonical_dir.string();
        std::string parent_str = resolved_parent.string();
        if (parent_str.compare(0, dir_str.length(), dir_str) != 0) {
            return false;
        }
        // Ensure the resolved parent is exactly the output directory
        // (or the boundary is a real path separator, not a prefix match).
        if (parent_str.length() > dir_str.length() &&
            parent_str[dir_str.length()] != '/') {
            return false;
        }
        return true;
    }

    std::string generate_temp_path(const std::string& filename) {
        return (fs::path(config_.temp_dir) / ("tmp_" + filename + ".partial")).string();
    }

    bool write_pdf_content(const std::string& temp_path, const std::string& content) {
        std::ofstream out(temp_path, std::ios::binary);
        if (!out.is_open()) return false;

        // Write PDF header
        out << "%PDF-1.4\n";
        out << "1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n";
        out << "2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n";
        out << "3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] >>\nendobj\n";
        out << content;
        out << "%%EOF\n";
        out.close();
        return out.good();
    }

    bool safe_move_to_final(const std::string& temp_path, const std::string& final_path) {
        // Use O_NOFOLLOW to atomically check and open without following symlinks
        // First, ensure the destination directory itself is not compromised
        fs::path dest_dir = fs::path(final_path).parent_path();
        int dir_fd = open(dest_dir.c_str(), O_RDONLY | O_DIRECTORY | O_NOFOLLOW);
        if (dir_fd < 0) {
            unlink(temp_path.c_str());
            return false;
        }

        std::string basename = fs::path(final_path).filename().string();

        // Check using fstatat with AT_SYMLINK_NOFOLLOW on the dir fd
        struct stat st;
        if (fstatat(dir_fd, basename.c_str(), &st, AT_SYMLINK_NOFOLLOW) == 0) {
            if (S_ISLNK(st.st_mode)) {
                std::cerr << "Security: symlink detected at destination" << std::endl;
                close(dir_fd);
                unlink(temp_path.c_str());
                return false;
            }
            if (!config_.overwrite_existing) {
                close(dir_fd);
                unlink(temp_path.c_str());
                return false;
            }
        }

        // Use renameat to atomically move within the verified directory context
        // The rename is atomic on the same filesystem and doesn't follow symlinks
        // at the target - it replaces whatever is at the target path
        fs::path temp_dir_path = fs::path(temp_path).parent_path();
        int temp_dir_fd = open(temp_dir_path.c_str(), O_RDONLY | O_DIRECTORY | O_NOFOLLOW);
        if (temp_dir_fd < 0) {
            close(dir_fd);
            unlink(temp_path.c_str());
            return false;
        }

        std::string temp_basename = fs::path(temp_path).filename().string();

        // Use linkat + unlinkat pattern for safe atomic move
        // renameat replaces target atomically without following symlinks
        int ret = renameat(temp_dir_fd, temp_basename.c_str(), dir_fd, basename.c_str());
        close(dir_fd);
        close(temp_dir_fd);

        if (ret != 0) {
            unlink(temp_path.c_str());
            return false;
        }
        return true;
    }

public:
    PDFGenerator(const PDFOutputConfig& config, int rate_limit = 10)
        : limiter_(rate_limit), config_(config) {
        fs::create_directories(config_.output_dir);
        fs::create_directories(config_.temp_dir);
    }

    bool generate_pdf(const std::string& filename, const std::string& content) {
        if (!validate_output_path(filename)) {
            std::cerr << "Invalid output path: " << filename << std::endl;
            return false;
        }

        std::string final_path = (fs::path(config_.output_dir) / filename).string();
        std::string temp_path = generate_temp_path(filename);

        auto generation_task = [&]() -> bool {
            if (!limiter_.try_acquire()) {
                return false;
            }

            std::lock_guard<std::mutex> lock(generation_mtx_);

            if (!write_pdf_content(temp_path, content)) {
                return false;
            }

            return safe_move_to_final(temp_path, final_path);
        };

        return RetryPolicy::execute_with_retry(generation_task);
    }
};

int main(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " <output_dir> <filename>" << std::endl;
        return 1;
    }

    PDFOutputConfig config(argv[1], "/tmp/pdf_gen", true);
    PDFGenerator generator(config);

    std::string content = "4 0 obj\n<< /Length 44 >>\nstream\nBT /F1 12 Tf 100 700 Td (Hello World) Tj ET\nendstream\nendobj\n";

    if (generator.generate_pdf(argv[2], content)) {
        std::cout << "PDF generated successfully" << std::endl;
        return 0;
    } else {
        std::cerr << "PDF generation failed" << std::endl;
        return 1;
    }
}
